            } else {
                chipsToBet = this.view.getDealerCallBetChips();
            }
        }
        Player winner = checkWinner();
        if(playerQuit){
            this.view.displayPlayerNameAndLeftOverChips(this.player);
            this.view.displayPlayerQuit();
        }
    }

